seiyaku Privacy {
    kotoage fn direct() authorize("UsePrivacy") {
        let Secret<int> value = crypto::private_input(0);
        if value { return; }
    }
}

seiyaku Privacy {
    fn relay(Secret<int> value) -> Secret<int> { return value; }
    kotoage fn transitive() authorize("UsePrivacy") {
        let Secret<int> value = crypto::private_input(0);
        if relay(value) { return; }
    }
}

seiyaku Privacy {
    kotoage fn expose() -> Secret<int> authorize("UsePrivacy") {
        return crypto::private_input(0);
    }
}

seiyaku Privacy {
    kotoage fn log_secret() authorize("UsePrivacy") {
        let Secret<int> value = crypto::private_input(0);
        debug::info(value);
    }
}

seiyaku Privacy {
    state Secret<int> leaked;
    hajimari() {}
}

seiyaku Privacy {
    state StateMap<int, int> values;
    kotoage fn write() authorize("UsePrivacy") {
        let Secret<int> key = crypto::private_input(0);
        values[key] = 1;
    }
}

seiyaku Privacy {
    state StateMap<int, int> values;
    kotoage fn write() authorize("UsePrivacy") {
        let Secret<int> value = crypto::private_input(0);
        values[0] = value;
    }
}

seiyaku Privacy {
    kotoage fn write() authorize("UsePrivacy") {
        let Secret<int> path = crypto::private_input(0);
        state::set(path: path, value: 1);
    }
}

seiyaku Privacy {
    kotoage fn query() authorize("UsePrivacy") {
        let Secret<int> id = crypto::private_input(0);
